create table if not exists market_source_sets(id uuid primary key default gen_random_uuid(),market_code text not null,language_code text not null,source_set_name text not null,source_group text not null check(source_group in ('local','english_comparison')),source_type text not null,connector_name text not null,enabled boolean not null default false,source_weight numeric not null default 1,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists topic_observations(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),market_code text not null,language_code text not null,source_set_id uuid not null references market_source_sets(id),topic text not null,time_window text not null,weighted_topic_documents numeric not null default 0,weighted_total_documents numeric not null default 0,smoothed_topic_share numeric,independent_source_count int not null default 0,total_document_count int not null default 0,average_entity_confidence numeric,source_quality_weight numeric,calculated_at timestamptz not null default now(),calculation_metadata_json jsonb not null default '{}');
create table if not exists cross_market_divergences(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),local_market_code text not null,comparison_market_code text not null default 'EN',topic text not null,time_window text not null,local_weighted_topic_documents numeric not null default 0,local_weighted_total_documents numeric not null default 0,english_weighted_topic_documents numeric not null default 0,english_weighted_total_documents numeric not null default 0,local_smoothed_topic_share numeric,english_smoothed_topic_share numeric,narrative_topic_gap numeric,log_odds_ratio_optional numeric,local_independent_source_count int not null default 0,english_independent_source_count int not null default 0,evidence_level text,entity_confidence numeric,comparison_status text not null check(comparison_status in ('available','unavailable','insufficient_data')),status text not null check(status in ('candidate','research_starting_point','insufficient_evidence','stale')),research_priority_score numeric,score_breakdown_json jsonb not null default '{}',limitations_json jsonb not null default '[]',methodology_version text not null default 'v1.0',surfaced_at timestamptz,last_updated_at timestamptz not null default now());
create index if not exists source_sets_market_idx on market_source_sets(market_code,language_code,enabled); create index if not exists observations_company_topic_idx on topic_observations(company_id,topic,time_window); create index if not exists divergences_priority_idx on cross_market_divergences(research_priority_score desc); create index if not exists divergences_status_idx on cross_market_divergences(status,comparison_status);
alter table market_source_sets enable row level security; alter table topic_observations enable row level security; alter table cross_market_divergences enable row level security;
create policy "public read enabled source sets" on market_source_sets for select using (enabled=true); create policy "public read topic observations" on topic_observations for select using (true); create policy "public read cross market divergences" on cross_market_divergences for select using (status='research_starting_point');
